"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["5540"],{32499(e){e.exports=JSON.parse('{"id":"FIN-541","slug":"withholding-tax","term":"Withholding Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Withholding tax is tax deducted at the source of income, such as from wages, interest or dividends, and paid directly to the government by the payer rather than by the person receiving the income.","explanation":["Withholding makes tax collection more reliable. Instead of waiting for individuals to pay tax at the end of the year, the government requires employers, banks and companies to deduct tax when they make payments.","The most common example is income tax withheld from wages. An employer calculates the tax due on each paycheck, deducts it and sends it to the tax authority. For example, an employee earning 4,000 a month might have 600 withheld, receiving 3,400 in pay.","Withholding also applies to investment income in many countries. Banks may withhold tax on interest, and companies may withhold tax on dividends, especially those paid to foreign investors. Tax treaties between countries often reduce these withholding rates for residents of treaty partners.","Withholding is usually a prepayment, not necessarily the final tax. At the end of the tax year, taxpayers may file a return that compares the tax withheld with the tax actually owed, leading to a refund if too much was withheld or a further payment if too little. In some cases, withholding is the final tax on that income and no further reporting is needed."],"note":"","total":1725,"prev":{"slug":"withdrawal-rate","term":"Withdrawal Rate"},"next":{"slug":"work-in-progress","term":"Work in Progress"}}')}}]);